import { useDashboardStore } from "@/store/dashboardStore.js";

class HttpClient {
  defaultOptions = {
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
    },
  };

  getBaseUrl() {
    const dashboardStore = useDashboardStore();
    const baseUrl = dashboardStore.getBaseUrl;
    if (!baseUrl) {
      throw new Error("Base URL is missing!");
    }
    return baseUrl;
  }
  getSpace3DURL() {
    const dashboardStore = useDashboardStore();
    const Space3DURL = dashboardStore.getSpace3DURL;
    if (!Space3DURL) {
      throw new Error("3DSpace URL is missing!");
    }
    return Space3DURL;
  }
  async request(method, endpoint, body, options = {}) {
    const { headers = {}, ...fetchOptions } = options;
    const dashboardStore = useDashboardStore();
    const url =
      endpoint.startsWith("http://") || endpoint.startsWith("https://")
        ? endpoint
        : endpoint.toLowerCase().endsWith("search")
        ? dashboardStore.getServer === "OnPremise"
          ? this.getBaseUrl() + endpoint
          : this.getBaseUrl().replace("-space.", "-fedsearch.") + endpoint + "?xrequestedwith=xmlhttprequest"
        : this.getSpace3DURL() + endpoint;
    const response = await fetch(url, {
      ...this.defaultOptions,
      ...fetchOptions,

      method,

      headers: {
        ...this.defaultOptions.headers,
        ...headers,
      },

      ...(body !== undefined && {
        body: JSON.stringify(body),
      }),
    });

    if (!response.ok) {
      const error = await response.text().catch(() => "");

      throw new Error(
        `${method} ${endpoint} failed (${response.status}) ${error}`,
      );
    }

    if (response.status === 204) {
      return null;
    }

    return response.json();
  }

  get(url, options) {
    return this.request("GET", url, undefined, options);
  }

  post(url, body, options) {
    return this.request("POST", url, body, options);
  }

  put(url, body, options) {
    return this.request("PUT", url, body, options);
  }

  patch(url, body, options) {
    return this.request("PATCH", url, body, options);
  }

  delete(url, options) {
    return this.request("DELETE", url, undefined, options);
  }
}

export default new HttpClient();
